import { forwardRef, useMemo } from 'react';

import { cn } from '../../utils';
import { Spinner } from '../Spinner';

import type { ButtonFSMState } from './Button.fsm';
import type { ButtonProps } from './Button.types';

// Visually-hidden styles for sr-only elements
const srOnlyStyle: React.CSSProperties = {
  position: 'absolute',
  width: '1px',
  height: '1px',
  margin: '-1px',
  padding: 0,
  overflow: 'hidden',
  clip: 'rect(0 0 0 0)',
  border: 0,
};

// Icon size dimensions (square button for icon-only use)
const ICON_SIZE_STYLE: React.CSSProperties = {
  width: '2.5rem',
  height: '2.5rem',
  padding: 0,
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
};

// Ghost variant base styles
const GHOST_BASE_STYLE: React.CSSProperties = {
  backgroundColor: 'transparent',
  border: 'none',
  color: 'inherit',
};

// Ghost variant hover/pressed styles
const GHOST_HOVER_STYLE: React.CSSProperties = {
  ...GHOST_BASE_STYLE,
  backgroundColor: 'var(--bs-tertiary-bg, rgba(0,0,0,0.05))',
};

/**
 * Determine if a variant is a subtle variant and extract its color.
 */
function parseSubtleVariant(variant: string): string | null {
  if (variant.startsWith('subtle-')) {
    return variant.slice(7);
  }
  return null;
}

/**
 * BaseButton - Presentational Button Component
 *
 * Receives visual state from the FSM and renders the button with appropriate
 * styling via Bootstrap classes and data-visual-state attribute.
 *
 * SECURITY: Prop spreading is restricted to a whitelist of safe HTML attributes.
 * Event handlers must be explicitly passed through the component API.
 */
export const BaseButton = forwardRef<
  HTMLButtonElement,
  ButtonProps & {
    fsmState: ButtonFSMState;
    onMouseEnter?: () => void;
    onMouseLeave?: () => void;
    onMouseDown?: (e: React.MouseEvent<HTMLButtonElement>) => void;
    onMouseUp?: () => void;
    onFocus?: () => void;
    onBlur?: () => void;
  }
>(
  (
    {
      children,
      variant = 'primary',
      size = 'md',
      disabled = false,
      loading = false,
      error = false,
      loadingText,
      loadingPosition = 'start',
      loadingIndicator,
      startIcon,
      endIcon,
      onClick,
      className = '',
      type = 'button',
      fullWidth = false,
      style,
      id,
      name,
      value,
      tabIndex,
      autoFocus,
      'aria-label': ariaLabel,
      'aria-describedby': ariaDescribedBy,
      'aria-controls': ariaControls,
      'aria-expanded': ariaExpanded,
      'aria-pressed': ariaPressed,
      'aria-haspopup': ariaHasPopup,
      'data-testid': dataTestId,
      'data-test': dataTest,
      title,
      form,
      formAction,
      formMethod,
      formNoValidate,
      formTarget,
      announceText,
      announce = !!announceText,
      fsmState,
      onMouseEnter,
      onMouseLeave,
      onMouseDown,
      onMouseUp,
      onFocus,
      onBlur,
    },
    ref
  ) => {
    // Button is disabled when explicitly disabled or loading
    const isDisabled = disabled || loading;

    // Parse subtle variant color
    const subtleColor = parseSubtleVariant(variant);
    const isGhost = variant === 'ghost';
    const isSubtle = subtleColor !== null;

    // Build Bootstrap class names - memoized to prevent unnecessary recalculation
    const bootstrapClasses = useMemo(() => {
      // Determine the variant class
      let variantClass: string;
      if (isGhost) {
        // Ghost: use btn base only, styles applied via style prop
        variantClass = '';
      } else if (isSubtle) {
        // Subtle: use Bootstrap subtle background utilities
        variantClass = `bg-${subtleColor}-subtle text-${subtleColor}-emphasis`;
      } else {
        // Standard Bootstrap variant
        variantClass = `btn-${variant}`;
      }

      return cn(
        'btn',
        variantClass,
        isSubtle && 'border-0',
        size === 'sm' && 'btn-sm',
        size === 'lg' && 'btn-lg',
        size === 'icon' && 'btn-sm', // Base sizing, exact dimensions via style
        fullWidth && 'w-100',
        error && 'btn-error',
        className
      );
    }, [variant, size, fullWidth, error, className, isGhost, isSubtle, subtleColor]);

    // Compute variant-specific styles (ghost uses FSM state for hover feedback)
    const computedStyle = useMemo<React.CSSProperties | undefined>(() => {
      const baseStyle: React.CSSProperties = {};

      // Ghost variant: dynamic background based on FSM hover/pressed state
      if (isGhost) {
        const isInteractive =
          fsmState.visualState === 'hovered' ||
          fsmState.visualState === 'pressed' ||
          fsmState.visualState === 'focused';
        Object.assign(baseStyle, isInteractive ? GHOST_HOVER_STYLE : GHOST_BASE_STYLE);
      }

      // Icon size: square dimensions
      if (size === 'icon') {
        Object.assign(baseStyle, ICON_SIZE_STYLE);
      }

      // Merge with user-provided style
      if (style || Object.keys(baseStyle).length > 0) {
        return { ...baseStyle, ...style };
      }
      return style;
    }, [isGhost, size, fsmState.visualState, style]);

    // Determine what content to show
    const showLoadingText = loading && loadingText;
    const displayText = showLoadingText ? loadingText : children;

    // Build the loading indicator element
    const loaderEl = loading
      ? loadingIndicator ?? (
          <Spinner
            size="sm"
            style={{
              display: 'inline-block',
            }}
            aria-hidden="true"
          />
        )
      : null;

    // Handle click - prevent if disabled or loading
    const handleClick = (e: React.MouseEvent<HTMLButtonElement>): void => {
      if (isDisabled) {
        e.preventDefault();
        return;
      }
      onClick?.(e);
    };

    // Build autoFocus props conditionally to avoid linter warnings
    const autoFocusProps = autoFocus ? { autoFocus: true as const } : {};

    // Render loading at center position (hides text, shows only spinner)
    const isCenterLoading = loading && loadingPosition === 'center';

    return (
      <>
        <button
          ref={ref}
          type={type}
          className={bootstrapClasses}
          disabled={isDisabled}
          onClick={handleClick}
          onMouseEnter={onMouseEnter}
          onMouseLeave={onMouseLeave}
          onMouseDown={onMouseDown}
          onMouseUp={onMouseUp}
          onFocus={onFocus}
          onBlur={onBlur}
          style={computedStyle}
          id={id}
          name={name}
          value={value}
          tabIndex={tabIndex}
          aria-label={ariaLabel}
          aria-describedby={ariaDescribedBy}
          aria-controls={ariaControls}
          aria-expanded={ariaExpanded}
          aria-pressed={ariaPressed}
          aria-haspopup={ariaHasPopup}
          aria-busy={loading}
          aria-disabled={isDisabled ? true : undefined}
          data-testid={dataTestId}
          data-test={dataTest}
          data-visual-state={fsmState.visualState}
          data-variant={isGhost ? 'ghost' : isSubtle ? `subtle-${subtleColor}` : undefined}
          title={title}
          form={form}
          formAction={formAction}
          formMethod={formMethod}
          formNoValidate={formNoValidate}
          formTarget={formTarget}
          {...autoFocusProps}
        >
          {isCenterLoading ? (
            /* Center loading: hide text, show only loader */
            <>
              <span style={{ visibility: 'hidden' }}>{displayText}</span>
              <span
                style={{
                  position: 'absolute',
                  display: 'inline-flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                }}
                aria-hidden="true"
              >
                {loaderEl}
              </span>
            </>
          ) : (
            /* Start/end loading or non-loading content */
            <>
              {/* Start icon or start-position spinner */}
              {loading && loadingPosition === 'start' && (
                <span className="me-2" aria-hidden="true">
                  {loaderEl}
                </span>
              )}
              {!loading && startIcon && (
                <span className="me-2" aria-hidden="true">
                  {startIcon}
                </span>
              )}

              <span>{displayText}</span>

              {/* End icon or end-position spinner */}
              {loading && loadingPosition === 'end' && (
                <span className="ms-2" aria-hidden="true">
                  {loaderEl}
                </span>
              )}
              {!loading && endIcon && (
                <span className="ms-2" aria-hidden="true">
                  {endIcon}
                </span>
              )}
            </>
          )}
        </button>

        {/* Announce state changes to screen readers */}
        {announce && announceText && (
          <output aria-live="polite" aria-atomic="true" style={srOnlyStyle}>
            {announceText}
          </output>
        )}

        {/* Spinner status region for screen readers (present whenever loading) */}
        {loading && !announceText && (
          <output aria-live="polite" aria-atomic="true" style={srOnlyStyle}>
            Loading
          </output>
        )}
      </>
    );
  }
);

BaseButton.displayName = 'BaseButton';

/**
 * Button Finite State Machine (FSM)
 *
 * Manages visual state transitions for the Button component using a
 * deterministic, pure reducer pattern. This ensures predictable visual
 * state behavior across hover, focus, press, and disabled states.
 *
 * State Diagram:
 * ```
 *            ENABLE
 *             ↓
 *    ┌────────────────┐
 *    │      idle      │ ← default state
 *    └────────────────┘
 *         ↑ ↓ ↓ ↑
 *    BLUR HOVER FOCUS BLUR/RELEASE
 *         ↓ ↑ ↑ ↓
 *    ┌────────────────┐
 *    │ hovered/focused│
 *    │   /pressed     │
 *    └────────────────┘
 *
 *    From any state:
 *    DISABLE → disabled
 *    LOADING → loading
 *    ERROR → error
 *    ENABLE → back to idle (if not loading/error)
 * ```
 *
 * Visual States:
 * - idle: default, no interaction
 * - hovered: mouse over the button
 * - focused: keyboard focus or focus-visible
 * - pressed: mouse down
 * - disabled: disabled prop is true
 * - loading: loading prop is true
 * - error: error prop is true
 *
 * Events:
 * - HOVER: mouse entered
 * - BLUR: mouse left or focus lost
 * - FOCUS: keyboard focus gained
 * - PRESS: mouse down (left button)
 * - RELEASE: mouse up
 * - DISABLE: disabled prop changed to true
 * - ENABLE: disabled prop changed to false
 * - LOADING: loading prop changed to true
 * - ERROR: error prop changed to true
 * - CLEAR_ERROR: error prop changed to false
 *
 * Rules:
 * 1. disabled/loading/error states override interactive states
 * 2. Once disabled, only ENABLE returns to idle
 * 3. Hover/focus/press have no effect when disabled, loading, or error
 * 4. Multiple interactions (e.g. hovered + focused) → pressed takes precedence
 * 5. Pure function: same input → same output, no side effects
 */

export type ButtonVisualState =
  | 'idle'
  | 'hovered'
  | 'focused'
  | 'pressed'
  | 'disabled'
  | 'loading'
  | 'error';

export type ButtonFSMEvent =
  | { type: 'HOVER' }
  | { type: 'BLUR' }
  | { type: 'FOCUS' }
  | { type: 'PRESS' }
  | { type: 'RELEASE' }
  | { type: 'DISABLE' }
  | { type: 'ENABLE' }
  | { type: 'LOADING'; payload: boolean }
  | { type: 'ERROR'; payload: boolean };

export interface ButtonFSMState {
  visualState: ButtonVisualState;
  isPressed: boolean;
  isHovered: boolean;
  isFocused: boolean;
  isDisabled: boolean;
  isLoading: boolean;
  isError: boolean;
}

/**
 * Pure reducer function for Button FSM
 *
 * @param state current FSM state
 * @param event event to process
 * @returns new FSM state
 *
 * @example
 * ```tsx
 * const [fsmState, dispatch] = useReducer(buttonFSMReducer, initialState);
 *
 * const handleMouseEnter = () => dispatch({ type: 'HOVER' });
 * const handleMouseLeave = () => dispatch({ type: 'BLUR' });
 * const handleFocus = () => dispatch({ type: 'FOCUS' });
 * const handleMouseDown = () => dispatch({ type: 'PRESS' });
 * const handleMouseUp = () => dispatch({ type: 'RELEASE' });
 * ```
 */
export function buttonFSMReducer(state: ButtonFSMState, event: ButtonFSMEvent): ButtonFSMState {
  switch (event.type) {
    // Override states: these take precedence over all others
    case 'DISABLE':
      return {
        visualState: 'disabled',
        isPressed: false,
        isHovered: false,
        isFocused: false,
        isDisabled: true,
        isLoading: state.isLoading,
        isError: state.isError,
      };

    case 'ENABLE':
      // If we're coming out of disabled, reset to idle (or previous state if loading/error)
      return {
        visualState: state.isLoading ? 'loading' : state.isError ? 'error' : 'idle',
        isPressed: false,
        isHovered: false,
        isFocused: false,
        isDisabled: false,
        isLoading: state.isLoading,
        isError: state.isError,
      };

    case 'LOADING':
      // If disabled, stay disabled even if loading state changes
      if (state.isDisabled) {
        return {
          ...state,
          isLoading: event.payload,
        };
      }
      // If transitioning TO loading, show loading but preserve interaction flags
      if (event.payload && !state.isLoading) {
        return {
          ...state,
          visualState: 'loading',
          isLoading: true,
        };
      }
      // If transitioning FROM loading, restore the previous interactive state
      if (!event.payload && state.isLoading) {
        return {
          ...state,
          visualState: state.isPressed
            ? 'pressed'
            : state.isFocused
              ? 'focused'
              : state.isHovered
                ? 'hovered'
                : 'idle',
          isLoading: false,
        };
      }
      // Loading state didn't change, return as-is
      return state;

    case 'ERROR':
      // If disabled, stay disabled even if error state changes
      if (state.isDisabled) {
        return {
          ...state,
          isError: event.payload,
        };
      }
      // If transitioning TO error, show error but preserve interaction flags
      if (event.payload && !state.isError) {
        return {
          ...state,
          visualState: 'error',
          isError: true,
        };
      }
      // If transitioning FROM error, restore the previous interactive state
      if (!event.payload && state.isError) {
        return {
          ...state,
          visualState: state.isPressed
            ? 'pressed'
            : state.isFocused
              ? 'focused'
              : state.isHovered
                ? 'hovered'
                : 'idle',
          isError: false,
        };
      }
      // Error state didn't change, return as-is
      return state;

    // Interactive states: only apply if not disabled, loading, or error
    case 'HOVER':
      if (state.isDisabled || state.isLoading || state.isError) {
        return state;
      }
      return {
        ...state,
        isHovered: true,
        visualState: state.isPressed ? 'pressed' : state.isFocused ? 'focused' : 'hovered',
      };

    case 'BLUR':
      // Disabled/loading states don't change on blur
      if (state.isDisabled || state.isLoading) {
        return state;
      }
      // During error state: if was focused, blur clears to idle; otherwise stay error
      if (state.isError) {
        if (state.isFocused) {
          return {
            ...state,
            isHovered: false,
            isPressed: false,
            isFocused: false,
            visualState: 'idle',
          };
        }
        // Not focused, just clear hover/press but stay in error
        return {
          ...state,
          isHovered: false,
          isPressed: false,
        };
      }
      return {
        ...state,
        isHovered: false,
        isPressed: false,
        isFocused: false,
        visualState: 'idle',
      };

    case 'FOCUS':
      if (state.isDisabled || state.isLoading || state.isError) {
        return state;
      }
      return {
        ...state,
        isFocused: true,
        visualState: state.isPressed ? 'pressed' : 'focused',
      };

    case 'PRESS':
      if (state.isDisabled || state.isLoading || state.isError) {
        return state;
      }
      return {
        ...state,
        isPressed: true,
        isHovered: true, // PRESS implies mouse is hovering
        visualState: 'pressed',
      };

    case 'RELEASE':
      if (state.isDisabled || state.isLoading || state.isError) {
        return state;
      }
      return {
        ...state,
        isPressed: false,
        visualState: state.isFocused ? 'focused' : state.isHovered ? 'hovered' : 'idle',
      };

    default:
      return state;
  }
}

/**
 * Create initial FSM state
 * @param disabled optional initial disabled state
 * @param loading optional initial loading state
 * @param error optional initial error state
 */
export function createInitialButtonFSMState(
  disabled = false,
  loading = false,
  error = false
): ButtonFSMState {
  const isDisabled = disabled;
  const isLoading = loading;
  const isError = error;

  let visualState: ButtonVisualState = 'idle';
  if (isDisabled) {
    visualState = 'disabled';
  } else if (isLoading) {
    visualState = 'loading';
  } else if (isError) {
    visualState = 'error';
  }

  return {
    visualState,
    isPressed: false,
    isHovered: false,
    isFocused: false,
    isDisabled,
    isLoading,
    isError,
  };
}

/* eslint jsx-a11y/no-autofocus: 0 */

import { forwardRef, useEffect, useReducer } from 'react';

import { BaseButton } from './BaseButton';
import { type ButtonFSMEvent, buttonFSMReducer, createInitialButtonFSMState } from './Button.fsm';

import type { ButtonProps } from './Button.types';

/**
 * Button Component with FSM State Management
 *
 * A versatile, accessible button component using Bootstrap 5 native classes
 * enhanced with Finite State Machine for visual state management.
 *
 * FSM manages visual states based on user interactions:
 * - idle: default state
 * - hovered: mouse over
 * - focused: keyboard focus
 * - pressed: mouse down
 * - disabled: disabled state (prop-driven)
 * - loading: loading state (prop-driven)
 * - error: error state (prop-driven)
 *
 * The FSM ensures predictable, consistent visual feedback for all interactions.
 *
 * DSAi design tokens are applied through the Bootstrap theme (dsai-theme-bs.css).
 * Supports multiple variants, sizes, states, icons, and loading with full WCAG 2.2 AA compliance.
 *
 * SECURITY: Prop spreading is restricted to a whitelist of safe HTML attributes only.
 * Event handlers must be explicitly passed through the component API.
 *
 * @see https://getbootstrap.com/docs/5.3/components/buttons/
 *
 * @example
 * ```tsx
 * // Primary button
 * <Button variant="primary" onClick={handleClick}>
 *   Click me
 * </Button>
 *
 * // Outline variant
 * <Button variant="outline-secondary" size="lg">
 *   Large Outline Button
 * </Button>
 *
 * // Loading state
 * <Button variant="primary" loading>
 *   Saving...
 * </Button>
 *
 * // With icons
 * <Button variant="success" startIcon={<CheckIcon />}>
 *   Save
 * </Button>
 *
 * // Error state
 * <Button variant="primary" error>
 *   Error occurred
 * </Button>
 *
 * // Full width button
 * <Button variant="success" fullWidth>
 *   Full Width
 * </Button>
 *
 * // With ref
 * const buttonRef = useRef<HTMLButtonElement>(null);
 * <Button ref={buttonRef} onClick={handleClick}>
 *   Button with Ref
 * </Button>
 *
 * // With aria-live announcements for async operations
 * <Button announceText="Saving changes..." loading>
 *   Save
 * </Button>
 * ```
 *
 * Accessibility Features (WCAG 2.2 AA):
 * - Semantic HTML `<button>` element
 * - Keyboard navigation (Enter, Space)
 * - Focus indicators (visible focus ring via Bootstrap)
 * - Disabled state with aria-disabled
 * - Loading state with aria-busy
 * - Decorative icons marked with aria-hidden="true"
 * - Dynamic state announcements via aria-live="polite"
 * - Sufficient color contrast (4.5:1 for normal text, 3:1 for large text)
 * - Touch target size ≥44×44px (WCAG 2.2 2.5.8)
 * - Focus Not Obscured (WCAG 2.2 2.4.11, 2.4.12)
 * - Consistent Help (WCAG 2.2 3.2.6)
 */
export const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  ({ disabled = false, loading = false, error = false, onClick, as, ...restProps }, ref) => {
    // Initialize FSM with current state
    const [fsmState, dispatch] = useReducer(
      buttonFSMReducer,
      { disabled, loading, error },
      (initialState) =>
        createInitialButtonFSMState(initialState.disabled, initialState.loading, initialState.error)
    );

    // Sync FSM with external prop changes
    useEffect(() => {
      if (disabled && !fsmState.isDisabled) {
        dispatch({ type: 'DISABLE' });
      } else if (!disabled && fsmState.isDisabled) {
        dispatch({ type: 'ENABLE' });
      }
    }, [disabled, fsmState.isDisabled]);

    useEffect(() => {
      dispatch({ type: 'LOADING', payload: loading });
    }, [loading]);

    useEffect(() => {
      dispatch({ type: 'ERROR', payload: error });
    }, [error]);

    // FSM event handlers
    const dispatchFSMEvent = (event: ButtonFSMEvent): void => {
      dispatch(event);
    };

    // Create wrapper handlers that dispatch FSM events and call user handlers
    const handleMouseEnter = (): void => {
      dispatchFSMEvent({ type: 'HOVER' });
    };

    const handleMouseLeave = (): void => {
      dispatchFSMEvent({ type: 'BLUR' });
    };

    const handleFocus = (): void => {
      dispatchFSMEvent({ type: 'FOCUS' });
    };

    const handleBlur = (): void => {
      dispatchFSMEvent({ type: 'BLUR' });
    };

    const handleMouseUp = (): void => {
      dispatchFSMEvent({ type: 'RELEASE' });
    };

    const handleClick = (e: React.MouseEvent<HTMLButtonElement>): void => {
      // Prevent click if disabled or loading
      if (disabled || loading) {
        e.preventDefault();
        return;
      }
      onClick?.(e);
    };

    // Note: onMouseDown for FSM - only respond to left button (button 0)
    const handleMouseDownFSM = (e: React.MouseEvent<HTMLButtonElement>): void => {
      // Only dispatch PRESS for left mouse button
      if (e.button === 0) {
        dispatchFSMEvent({ type: 'PRESS' });
      }
    };

    return (
      <BaseButton
        ref={ref}
        {...restProps}
        as={as}
        disabled={disabled}
        loading={loading}
        error={error}
        onClick={handleClick}
        fsmState={fsmState}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        onFocus={handleFocus}
        onBlur={handleBlur}
        onMouseDown={handleMouseDownFSM}
        onMouseUp={handleMouseUp}
      />
    );
  }
);

Button.displayName = 'Button';

import type {
  SafeHTMLAttributes as BaseSafeHTMLAttributes,
  ComponentSize,
  SemanticColorVariant,
  PolymorphicComponentProps,
} from '../../types';
import type { CSSProperties, MouseEvent, ReactNode } from 'react';

/**
 * Button component variants
 * Maps to Bootstrap 5 button styles using design tokens
 *
 * - Solid: 'primary', 'secondary', etc. — filled background
 * - Outline: 'outline-primary', etc. — bordered, transparent background
 * - Subtle: 'subtle-primary', etc. — lighter background using Bootstrap subtle utilities
 * - Ghost: transparent background with subtle hover feedback
 * - Link: styled as a hyperlink
 *
 * @see SemanticColorVariant
 */
export type ButtonVariant =
  | SemanticColorVariant
  | `outline-${SemanticColorVariant}`
  | `subtle-${SemanticColorVariant}`
  | 'ghost'
  | 'link';

/**
 * Button component sizes
 * sm: Small button (0.875rem font size)
 * md: Medium button (1rem font size) - default
 * lg: Large button (1.25rem font size)
 * icon: Square button for icon-only use (2.5rem × 2.5rem)
 * @see ComponentSize
 */
export type ButtonSize = ComponentSize | 'icon';

/**
 * Button HTML type attribute
 */
export type ButtonType = 'button' | 'submit' | 'reset';

/**
 * Safe HTML attributes that can be spread onto the button element
 * SECURITY: This whitelist prevents injection of dangerous attributes or event handlers
 * @see BaseSafeHTMLAttributes
 */
export interface SafeHTMLAttributes extends BaseSafeHTMLAttributes<HTMLButtonElement> {
  /** Associate button with a form by ID */
  form?: string;
  /** Override form action URL */
  formAction?: string;
  /** Override form HTTP method */
  formMethod?: 'get' | 'post' | 'dialog';
  /** Bypass form validation */
  formNoValidate?: boolean;
  /** Override form target */
  formTarget?: string;
}

/**
 * Button component props
 *
 * @example
 * ```tsx
 * // Basic button
 * <Button variant="primary" size="md" onClick={handleClick}>
 *   Click me
 * </Button>
 *
 * // Loading button
 * <Button variant="primary" loading>
 *   Saving...
 * </Button>
 *
 * // Button with icons
 * <Button variant="primary" startIcon={<SaveIcon />} endIcon={<ArrowIcon />}>
 *   Save
 * </Button>
 * ```
 */
export type ButtonElement = 'button';

export interface ButtonOwnProps extends SafeHTMLAttributes {
  /**
   * Button content
   */
  children: ReactNode;

  /**
   * Button visual style variant
   * @default 'primary'
   */
  variant?: ButtonVariant;

  /**
   * Button size
   * @default 'md'
   */
  size?: ButtonSize;

  /**
   * Disabled state - prevents user interaction
   * @default false
   */
  disabled?: boolean;

  /**
   * Loading state - shows spinner and disables button
   * @default false
   */
  loading?: boolean;

  /**
